-- 0015_social_press_enrichment (down)
-- Reverses the up migration: removes the three 2026 press clippings and
-- the social settings, and restores the exhibition descriptions and page
-- sections to their migration-0013 state.

--> statement-breakpoint
DELETE FROM `news_articles` WHERE `slug` IN ('himani-shah-inaugurates-embodied-enlightenment', 'himani-inaugurates-art-exhibition-kathmandu', 'art-exhibition-opens-at-bodhisattva');
--> statement-breakpoint
DELETE FROM `site_settings` WHERE `setting_key` IN ('social_instagram', 'social_facebook');
--> statement-breakpoint
UPDATE `exhibitions` SET `description` = 'A retrospective exhibition of Samundra Man Singh Shrestha by Bodhisattva International. For the first time in the history of Nepali art, an exhibition is re-celebrated a decade later: Embodied Enlightenment returns, bringing audiences back to the original 2016 retrospective while revealing how its artist has evolved over the past ten years. Works from the private collection of Anjana and the late Purna Man Shakya, originally presented in the landmark exhibition, are shown alongside new and previously unseen works by the artist. Inaugurated by former Crown Princess Himani Shah; open daily 12 PM – 7 PM, entry Rs. 200 in support of the Prime Minister''s Disaster Relief Fund.' WHERE `slug` = 'ten-years-of-celebrating-embodied-enlightenment';
--> statement-breakpoint
UPDATE `exhibitions` SET `description` = 'A first-of-its-kind solo exhibition dedicated to a traditional Newa statue maker, celebrating one of Nepal''s senior living master wax-model makers at the age of 83. Spanning the 1990s to 2026, it brought together early works and final cast statues in bronze, copper and silver, all from the collections of Anjana Shakya, the late Purna Man Shakya and Bodhisattva Gallery. Inaugurated by Deputy Mayor of Lalitpur Manjali Shakya Bajracharya, with a special edition catalogue documenting his contribution to traditional Newa statue making.' WHERE `slug` = 'the-art-of-babu-kaji-bajracharya';
--> statement-breakpoint
UPDATE `exhibitions` SET `description` = REPLACE(`description`, ' Ten years on, the retrospective was revisited as ''10 Years of Celebrating Embodied Enlightenment'' at the Purna Museum of Newa Art & Bodhisattva Gallery, Kupondole (16 November – 27 December 2026), where artists from the original exhibition were honoured at the inauguration.', '') WHERE `slug` = 'embodied-enlightenment-2016';
--> statement-breakpoint
UPDATE `page_sections` ps JOIN `pages` p ON (ps.`revision_id` = p.`published_revision_id` OR ps.`revision_id` = p.`draft_revision_id`) SET ps.`config` = '{"sectionLabel":"History","heading":"A History of Collecting","items":[{"yearLabel":"1980s","text":"Anjana and Purna Man Shakya begin commissioning and collecting masterworks of Newa art — the beginnings of Bodhisattva."},{"yearLabel":"2011","text":"Jewels of Newar Art at Siddhartha Art Gallery presents the collection to wide acclaim; the Jewels of Newar Art book is launched."},{"yearLabel":"2019","text":"Bodhisattva Gallery opens its permanent home in Pulchowk, Lalitpur; works from the collection travel to Nepal Art Now at the Weltmuseum Wien."},{"yearLabel":"2023","text":"Purna Museum of Newa Art opens with A Collector''s Collection; the Bodhisattva Foundation establishes the Purna Man Shakya Memorial Art Award."},{"yearLabel":"2026","text":"10 Years of Celebrating Embodied Enlightenment revisits Samundra Man Singh Shrestha''s landmark 2016 retrospective."}]}' WHERE p.`slug` = 'museum' AND ps.`sort_order` = 2;
--> statement-breakpoint
UPDATE `page_sections` ps JOIN `pages` p ON (ps.`revision_id` = p.`published_revision_id` OR ps.`revision_id` = p.`draft_revision_id`) SET ps.`config` = '{"sectionLabel":"History","headingLine1":"Founded in Conviction.","headingAccent":"Grown in Purpose.","paragraphs":["Bodhisattva International was founded in the 1980s by Anjana Shakya and her late husband Purna Man Shakya, guided by a philosophy they called ''The Art of Living''. What began as a commitment to commissioning and collecting the finest Newa art grew into a family mission: to build a renaissance of contemporary traditional Newa art, made to museum quality rather than for mass production.","Through Bodhisattva Gallery, the family has presented more than 24 major exhibitions in Nepal and abroad — from Jewels of Newar Art in Kathmandu to Nepal Art Now at the Weltmuseum Wien — and contributed works to international museum collections. In 2023 the Purna Museum of Newa Art opened in Kupondole, Lalitpur, housing the couple''s permanent collection: the world''s largest private collection dedicated to contemporary traditional Newa art.","Today Bodhisattva International unites four arms — the Purna Museum of Newa Art, Bodhisattva Gallery, the Bodhisattva Foundation, and the Bodhisattva Gift Shop — preserving sacred knowledge, nurturing artists, and building bridges across generations and geographies."],"image":{"url":"/images/pages/about-history.jpg","alt":"Painted Lakhey mask from the Nepal Art Now exhibition at Weltmuseum Wien"},"imageAspect":"16:9","quote":{"text":"Art is not only to be preserved, but lived; not only to be admired, but experienced; and not only to represent culture, but to sustain it.","attribution":"Bodhisattva International"}}' WHERE p.`slug` = 'about' AND ps.`sort_order` = 1;
--> statement-breakpoint
UPDATE `page_sections` ps JOIN `pages` p ON (ps.`revision_id` = p.`published_revision_id` OR ps.`revision_id` = p.`draft_revision_id`) SET ps.`config` = '{"sectionLabel":"Our Mission","headingLine1":"Art as an Act","headingAccent":"of Responsibility","paragraphs":["Beyond the realm of art, the Bodhisattva Foundation extends the founders'' legacy into society. It is dedicated to humanitarian work, education, and the nurturing of emerging artists. Its most significant initiative is the Purna Man Shakya Memorial Art Award, which honours the founders'' philosophy of artistic excellence for both senior and emerging artists.","Beyond his role as a cultural visionary, the late Purna Man Shakya was deeply committed to humanitarian values — supporting children''s education, funding medical treatment for those in need, and offering protection and support to individuals during Nepal''s periods of political conflict. Today those values live on through the Foundation."],"image":{"url":"/images/pages/foundation-mission.jpg","alt":"Third Purna Man Shakya Memorial Art Award 2025 poster"},"imageAspect":"4:3"}' WHERE p.`slug` = 'foundation' AND ps.`sort_order` = 2;
